TOOL_SCOPES = {
    "search_docs": {"read"},
    "run_readonly_sql": {"read"},
    "create_refund": {"write", "refunds"},
}
ROLE_SCOPES = {"viewer": {"read"}, "support": {"read", "write", "refunds"}}

def authorize(role, tool):
    needed = TOOL_SCOPES.get(tool)
    if needed is None:
        return "deny: unknown tool"
    missing = sorted(needed - ROLE_SCOPES[role])
    return "allow" if not missing else f"deny: missing {missing}"

for role, tool in [("viewer", "search_docs"), ("viewer", "create_refund"),
                   ("support", "create_refund"), ("support", "drop_table")]:
    print(role, tool, "->", authorize(role, tool))
